const page = (title, body, color) => '<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>FRUiTIFY</title></head><body style="font-family:Arial,sans-serif;max-width:520px;margin:40px auto;padding:0 16px;color:#222"><h2 style="color:' + color + '">' + title + '</h2>' + body + '</body></html>';
{ const qa = $('Link opened').first().json.query || {};
  if (qa.all === '1') {
    if (qa.k !== '<APPROVAL_KEY>') return [{ json: { html: page('Link not valid', '') } }];
    const rowsA = $input.all().map(r => r.json);
    const waitingA = rowsA.filter(r => String(r.Status).startsWith('New') && String(r['DM pitch'] || '').trim()).length;
    return [{ json: { html: page('Approve all?', '<p><b>' + waitingA + '</b> vendors are waiting for your OK. Tapping the button approves the best-fit ones, up to today\'s daily limit.</p><form method="POST" onsubmit="var b=this.querySelector(\'button\');b.disabled=true;b.textContent=\'Approving… please wait\';"><input type="hidden" name="k" value="' + qa.k + '"><input type="hidden" name="all" value="1"><button style="background:#1f7a4a;color:#fff;border:0;padding:14px 26px;border-radius:8px;font-size:17px">Approve all (up to daily limit)</button></form>') } }];
  } }

const q = $('Link opened').first().json.query || {};
const esc = s => String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/"/g,'&quot;');
let html;
if (q.k !== '<APPROVAL_KEY>') html = page('Link not valid', '', '#a00');
else {
  const row = $('Read CRM (for page)').all().map(r => r.json).find(r => String(r.Instagram).toLowerCase() === String(q.u || '').toLowerCase());
  if (!row) html = page('Vendor not found', '', '#a00');
  else {
    const skip = q.a === 'skip';
    const body = '<p><b>' + esc(row.Name) + '</b> (@' + esc(row.Instagram) + ')<br>' + esc(row.Region) + ' - ' + esc(row.Language) + '</p><p>Current status: <b>' + esc(row.Status) + '</b></p><div style="background:#f3f8f5;padding:10px;border-radius:8px">' + esc(row['DM pitch']) + '</div>' +
      '<form method="POST" style="margin-top:18px"><input type="hidden" name="u" value="' + esc(row.Instagram) + '"><input type="hidden" name="a" value="' + (skip ? 'skip' : 'approve') + '"><input type="hidden" name="k" value="' + esc(q.k) + '">' +
      '<button style="background:' + (skip ? '#777' : '#1f7a4a') + ';color:#fff;border:0;padding:12px 24px;border-radius:8px;font-size:16px">Confirm ' + (skip ? 'Skip' : 'Approve') + '</button></form>';
    html = page((skip ? 'Skip' : 'Approve') + ' this vendor?', body, '#1f5f3f');
  }
}
return [{ json: { html } }];

// DAILY SEND LIMIT - change here (start 25-30, later up to 40)
const DAILY_LIMIT = 30;
const VOICES = { male: 'Charon', female: 'Kore' };
const PHONE_DIGITS = '919611701149';   // campaign number +91 96117 01149
const LANG = {
  'hi-IN': { plus: 'प्लस', d: ['शून्य','एक','दो','तीन','चार','पाँच','छह','सात','आठ','नौ'], brand: 'फ्रूटिफाई' },
  'mr-IN': { plus: 'प्लस', d: ['शून्य','एक','दोन','तीन','चार','पाच','सहा','सात','आठ','नऊ'], brand: 'फ्रूटिफाय' },
  'gu-IN': { plus: 'પ્લસ', d: ['શૂન્ય','એક','બે','ત્રણ','ચાર','પાંચ','છ','સાત','આઠ','નવ'], brand: 'ફ્રૂટિફાય' },
  'bn-IN': { plus: 'প্লাস', d: ['শূন্য','এক','দুই','তিন','চার','পাঁচ','ছয়','সাত','আট','নয়'], brand: 'ফ্রুটিফাই' },
  'ta-IN': { plus: 'பிளஸ்', d: ['பூஜ்யம்','ஒன்று','இரண்டு','மூன்று','நான்கு','ஐந்து','ஆறு','ஏழு','எட்டு','ஒன்பது'], brand: 'ஃப்ரூட்டிஃபை' },
  'te-IN': { plus: 'ప్లస్', d: ['సున్నా','ఒకటి','రెండు','మూడు','నాలుగు','ఐదు','ఆరు','ఏడు','ఎనిమిది','తొమ్మిది'], brand: 'ఫ్రూటిఫై' },
  'kn-IN': { plus: 'ಪ್ಲಸ್', d: ['ಸೊನ್ನೆ','ಒಂದು','ಎರಡು','ಮೂರು','ನಾಲ್ಕು','ಐದು','ಆರು','ಏಳು','ಎಂಟು','ಒಂಬತ್ತು'], brand: 'ಫ್ರೂಟಿಫೈ' },
  'ml-IN': { plus: 'പ്ലസ്', d: ['പൂജ്യം','ഒന്ന്','രണ്ട്','മൂന്ന്','നാല്','അഞ്ച്','ആറ്','ഏഴ്','എട്ട്','ഒമ്പത്'], brand: 'ഫ്രൂട്ടിഫൈ' },
  'pa-IN': { plus: 'ਪਲੱਸ', d: ['ਸਿਫ਼ਰ','ਇੱਕ','ਦੋ','ਤਿੰਨ','ਚਾਰ','ਪੰਜ','ਛੇ','ਸੱਤ','ਅੱਠ','ਨੌਂ'], brand: 'ਫਰੂਟੀਫਾਈ' },
  'en-IN': { plus: 'plus', d: ['zero','one','two','three','four','five','six','seven','eight','nine'], brand: 'Fruitify' }
};
const say = (L, s) => s.split('').map(x => L.d[+x]).join(' ');

const LANG_BY_NAME = { tamil:'ta-IN', gujarati:'gu-IN', marathi:'mr-IN', bengali:'bn-IN', telugu:'te-IN', kannada:'kn-IN', malayalam:'ml-IN', punjabi:'pa-IN', english:'en-IN' };
const b = $('Confirmed').first().json.body || {};
const rows = $('Read CRM').all().map(r => r.json).filter(r => r.Instagram);
const today = $now.setZone('Asia/Kolkata').toFormat('yyyy-MM-dd');
if (b.k !== '<APPROVAL_KEY>') return [{ json: { action: 'invalid' } }];
if (b.k === '<APPROVAL_KEY>' && b.all === '1') {
  const doneToday = rows.filter(r => String(r['Approved on']).startsWith(today)).length;
  const room = Math.max(0, DAILY_LIMIT - doneToday);
  const pend = rows.filter(r => String(r.Status).startsWith('New') && String(r['DM pitch'] || '').trim())
    .sort((x, y) => String(y.Date).localeCompare(String(x.Date)) || ((+y['Fit score'] || 0) - (+x['Fit score'] || 0)));
  const pick = pend.slice(0, room);
  return [{ json: { action: 'bulk', count: pick.length, waiting: pend.length, already: doneToday, limit: DAILY_LIMIT, items: pick.map((r, i) => build(r, doneToday + i + 1).json) } }];
}
const row = rows.find(r => String(r.Instagram).toLowerCase() === String(b.u || '').toLowerCase());
if (!row) return [{ json: { action: 'notfound' } }];
if (b.a === 'skip') return [{ json: { action: 'skip', u: row.Instagram, name: row.Name } }];
if (String(row.Status).startsWith('Approved') || String(row.Status).startsWith('Sent')) return [{ json: { action: 'already', u: row.Instagram, name: row.Name, status: row.Status } }];
const approvedToday = rows.filter(r => String(r['Approved on']).startsWith(today)).length;
if (approvedToday >= DAILY_LIMIT) return [{ json: { action: 'limit', limit: DAILY_LIMIT, name: row.Name } }];
return [build(row, approvedToday + 1)];

function build(row, __n) {
let lang = row['Voice language'];
if (!LANG[lang]) { const k = Object.keys(LANG_BY_NAME).find(n => String(row.Language).toLowerCase().includes(n)); lang = k ? LANG_BY_NAME[k] : 'hi-IN'; }
const L = LANG[lang];
const gender = /female/i.test(row['Voice speaker'] || '') ? 'female' : 'male';
const phone = L.plus + ' ' + say(L, PHONE_DIGITS.slice(0, 2)) + ', ' + say(L, PHONE_DIGITS.slice(2, 7)) + ', ' + say(L, PHONE_DIGITS.slice(7));
const text = String(row['Voice script'] || '').split('{{PHONE}}').join(phone).split('{{BRAND}}').join(L.brand)
  .replace(/FRUiTIFY|Fruitify|FRUITIFY/g, L.brand).replace(/\+?\s?91[\s-]?96117[\s-]?01149/g, phone);
return { json: { action: 'approve', u: row.Instagram, name: row.Name, platform: row.Platform || 'Instagram', pitch: row['DM pitch'], msgLink: row['Message link'] || ('https://ig.me/m/' + row.Instagram), approvedNo: __n, limit: DAILY_LIMIT, today,
  fileName: today + '_' + row.Instagram + '.mp3',
  ttsRequest: { input: { text }, voice: { languageCode: lang, name: lang + '-Chirp3-HD-' + VOICES[gender] }, audioConfig: { audioEncoding: 'MP3', speakingRate: 1.05 } } } };
}

const src = $('Decide').first().json.action === 'bulk' ? $('Bulk items').all().map(i => i.json) : [$('Decide').first().json];
return $input.all().map((it, i) => { const d = src[i] || src[0]; const a = it.json.audioContent;
  if (!a) return { json: { ...d, voiceError: true } };
  return { json: d, binary: { data: { data: a, mimeType: 'audio/mpeg', fileName: d.fileName, fileExtension: 'mp3' } } }; });

const page = (title, body, color) => '<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>FRUiTIFY</title></head><body style="font-family:Arial,sans-serif;max-width:520px;margin:40px auto;padding:0 16px;color:#222"><h2 style="color:' + color + '">' + title + '</h2>' + body + '</body></html>';
const d = $('Decide').first().json;
if (d.action === 'bulk') return [];
const esc = s => String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;');
const M = {
  approve: ['Approved', '#1f7a4a', esc(d.name) + ' is in today\'s send queue (' + d.approvedNo + ' of ' + d.limit + ' today). The voice note is ready in your Google Drive.'],
  skip: ['Skipped', '#555', esc(d.name) + ' will not be contacted.'],
  already: ['Already done', '#555', esc(d.name) + ' is already: ' + esc(d.status) + '.'],
  limit: ['Daily limit reached', '#a15c00', 'Today\'s limit of ' + d.limit + ' approvals is reached. ' + esc(d.name) + ' stays in the list for another day.'],
  invalid: ['Link not valid', '#a00', ''], notfound: ['Vendor not found', '#a00', '']
}[d.action] || ['Done', '#555', ''];
let extra = '';
if (d.action === 'approve' && d.platform === 'Facebook') {
  extra = '<p><b>Facebook vendor - please send this one yourself:</b></p><div id="p" style="background:#f3f8f5;padding:10px;border-radius:8px;white-space:pre-wrap">' + esc(d.pitch) + '</div>' +
    '<p style="margin-top:12px"><button onclick="navigator.clipboard.writeText(document.getElementById(\'p\').innerText).then(()=>{this.innerText=\'Copied\'})" style="background:#1f7a4a;color:#fff;border:0;padding:12px 20px;border-radius:8px;font-size:16px">Copy pitch</button> &nbsp; <a href="' + esc(d.msgLink) + '" style="font-size:16px">Open Messenger</a></p>';
}
return [{ json: { html: page(M[0], '<p>' + M[2] + '</p>' + extra + '<p style="color:#888;font-size:13px">You can close this page and go back to the email.</p>', M[1]) } }];

const page = (title, body, color) => '<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>FRUiTIFY</title></head><body style="font-family:Arial,sans-serif;max-width:520px;margin:40px auto;padding:0 16px;color:#222"><h2 style="color:' + color + '">' + title + '</h2>' + body + '</body></html>';
const d = $json;
const fb = d.items.filter(x => x.platform === 'Facebook').length;
return [{ json: { html: page('Approved ✓', '<p><b>' + d.count + '</b> vendors approved' + (d.already ? ' (plus ' + d.already + ' approved earlier today)' : '') + '. Daily limit: ' + d.limit + '.</p>' + (d.waiting > d.count ? '<p>' + (d.waiting - d.count) + ' more stay in the list for the coming days.</p>' : '') + '<p>Their voice notes are being made now (about 2 minutes). Claude will prepare the Instagram chats for you to press Send.</p>' + (fb ? '<p>' + fb + ' of them are Facebook pages - their pitch is in the CRM sheet to send yourself.</p>' : '') + '<p style="color:#888">You can close this page.</p>') } }];
